"""Export API generating CSV and PDF Activity Points Files (SPEC §11.4)."""

import csv
import io

from fastapi import APIRouter, HTTPException, Query
from fastapi.responses import Response
from fpdf import FPDF
from fpdf.enums import XPos, YPos

from app.engine.aggregator import evaluate
from app.schemas.profile import StudentProfile
from app.schemas.result import EngineResult
from app.storage import store

router = APIRouter(prefix="/api/export", tags=["export"])

DISCLAIMER_TEXT = (
    "NOTICE: This Activity Points Summary is an unofficial advisory document generated by "
    "the KTU Activity Points Checker aid. It does not replace the official Activity Points "
    "register maintained by the Institution and APJ Abdul Kalam Technological University. "
    "All awards remain subject to verification and formal endorsement by the Staff Advisor "
    "(SFA) and Head of Department (HoD)."
)


def generate_csv(engine_res: EngineResult, profile: StudentProfile) -> str:
    output = io.StringIO()
    writer = csv.writer(output)

    writer.writerow(["APJ ABDUL KALAM TECHNOLOGICAL UNIVERSITY - 2024 SCHEME"])
    writer.writerow(["ACTIVITY POINTS SUMMARY FILE (UNOFFICIAL STUDENT RECORD)"])
    writer.writerow([])
    writer.writerow(["Student ID", profile.student_id])
    writer.writerow(["Full Name", profile.full_name])
    writer.writerow(["Programme", profile.programme])
    writer.writerow(["Admission Date", str(profile.admission_date)])
    writer.writerow(["Programme End Date", str(profile.programme_end_date)])
    writer.writerow(["Entry Type", profile.entry_type.value])
    writer.writerow(["PwD Eligible", "Yes" if profile.is_pwd else "No"])
    writer.writerow(["Curriculum Scheme", profile.scheme])
    writer.writerow([])
    writer.writerow(["DISCLAIMER", DISCLAIMER_TEXT])
    writer.writerow([])

    # Activity Table
    writer.writerow([
        "Certificate ID",
        "Rule ID",
        "Group",
        "Activity Title",
        "Event / Details",
        "Level",
        "Position",
        "Verdict",
        "Confirmed Points",
        "Upper Bound Points",
        "Doubt Codes",
    ])

    for act in engine_res.activities:
        writer.writerow([
            act.certificate_id,
            act.rule_id,
            act.group,
            act.activity_title or "",
            "",
            "",
            "",
            act.verdict,
            act.counted_points_pessimistic,
            act.counted_points_optimistic,
            "; ".join(act.doubt_codes),
        ])

    writer.writerow([])
    writer.writerow(["SUMMARY BRACKETS"])
    writer.writerow(["Group", "Required", "Confirmed", "Pending", "Upper Bound", "Credit Status"])
    for gid in ["I", "II", "III"]:
        grp = engine_res.groups[gid]
        writer.writerow([
            f"Group {gid}",
            grp.required_points,
            grp.bracket.confirmed,
            grp.bracket.pending,
            grp.bracket.upper_bound,
            (
                "Achieved"
                if grp.is_credit_achieved_confirmed
                else ("Achievable" if grp.is_credit_achievable_upper else "Deficit")
            ),
        ])

    writer.writerow([
        "TOTAL",
        engine_res.required_total,
        engine_res.total_bracket.confirmed,
        engine_res.total_bracket.pending,
        engine_res.total_bracket.upper_bound,
        engine_res.credit_status,
    ])

    writer.writerow([])
    writer.writerow(["CREDITS CONFIRMED", f"{engine_res.credits_earned_confirmed} / 3"])
    writer.writerow(["CREDITS UPPER BOUND", f"{engine_res.credits_earned_upper} / 3"])
    writer.writerow([])
    writer.writerow(["SIGNATURE AND ENDORSEMENT"])
    writer.writerow(["Student Signature:", "___________________________", "Date:", "____________"])
    writer.writerow(
        ["Staff Advisor (SFA):", "___________________________", "Date:", "____________"]
    )
    writer.writerow(["Head of Department:", "___________________________", "Date:", "____________"])

    return output.getvalue()


def generate_pdf(engine_res: EngineResult, profile: StudentProfile) -> bytes:
    pdf = FPDF(orientation="P", unit="mm", format="A4")
    pdf.set_auto_page_break(auto=True, margin=15)
    pdf.add_page()

    # Title Banner
    pdf.set_font("Helvetica", "B", 14)
    pdf.cell(0, 8, "APJ ABDUL KALAM TECHNOLOGICAL UNIVERSITY", new_x=XPos.LMARGIN, new_y=YPos.NEXT, align="C")
    pdf.set_font("Helvetica", "B", 11)
    pdf.cell(0, 6, "ACTIVITY POINTS SUMMARY FILE - 2024 SCHEME", new_x=XPos.LMARGIN, new_y=YPos.NEXT, align="C")
    pdf.set_font("Helvetica", "I", 8)
    pdf.cell(0, 5, "(Independent Student Advisory Record - Rule viii)", new_x=XPos.LMARGIN, new_y=YPos.NEXT, align="C")
    pdf.ln(3)

    # Student Details Box
    pdf.set_fill_color(240, 243, 246)
    pdf.rect(10, pdf.get_y(), 190, 24, "F")
    pdf.set_font("Helvetica", "B", 9)
    pdf.cell(30, 6, "Student ID:", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "", 9)
    pdf.cell(65, 6, str(profile.student_id), new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "B", 9)
    pdf.cell(30, 6, "Entry Type:", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "", 9)
    pdf.cell(
        65,
        6,
        f"{profile.entry_type.value.capitalize()} (Req: {engine_res.required_total} pts)",
        new_x=XPos.LMARGIN,
        new_y=YPos.NEXT,
    )

    pdf.set_font("Helvetica", "B", 9)
    pdf.cell(30, 6, "Full Name:", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "", 9)
    pdf.cell(65, 6, str(profile.full_name), new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "B", 9)
    pdf.cell(30, 6, "PwD Category:", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "", 9)
    pdf.cell(65, 6, "Yes" if profile.is_pwd else "No", new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.set_font("Helvetica", "B", 9)
    pdf.cell(30, 6, "Programme:", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "", 9)
    pdf.cell(65, 6, str(profile.programme), new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "B", 9)
    pdf.cell(30, 6, "Study Window:", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.set_font("Helvetica", "", 9)
    pdf.cell(65, 6, f"{profile.admission_date} to {profile.programme_end_date}", new_x=XPos.LMARGIN, new_y=YPos.NEXT)
    pdf.ln(4)

    # Summary Table
    pdf.set_font("Helvetica", "B", 10)
    pdf.cell(0, 6, "1. Points & Credit Summary (Confirmed / Pending / Upper Bound)", new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.set_font("Helvetica", "B", 8)
    pdf.set_fill_color(225, 230, 235)
    pdf.cell(35, 6, "Group", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, "Required", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, "Confirmed", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, "Pending (+)", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, "Upper Bound", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(35, 6, "1-Credit Status", 1, align="C", fill=True, new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.set_font("Helvetica", "", 8)
    for gid in ["I", "II", "III"]:
        grp = engine_res.groups[gid]
        c_status = (
            "Achieved"
            if grp.is_credit_achieved_confirmed
            else ("Pending" if grp.is_credit_achievable_upper else "Deficit")
        )
        pdf.cell(35, 6, f"Group {gid}", 1, new_x=XPos.RIGHT, new_y=YPos.TOP)
        pdf.cell(30, 6, f"{grp.required_points} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
        pdf.cell(30, 6, f"{grp.bracket.confirmed} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
        pdf.cell(30, 6, f"+{grp.bracket.pending} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
        pdf.cell(30, 6, f"{grp.bracket.upper_bound} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
        pdf.cell(35, 6, c_status, 1, align="C", new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.set_font("Helvetica", "B", 8)
    pdf.cell(35, 6, "TOTAL", 1, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, f"{engine_res.required_total} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, f"{engine_res.total_bracket.confirmed} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, f"+{engine_res.total_bracket.pending} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(30, 6, f"{engine_res.total_bracket.upper_bound} pts", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(35, 6, engine_res.credit_status, 1, align="C", new_x=XPos.LMARGIN, new_y=YPos.NEXT)
    pdf.ln(4)

    # Activity Breakdown Table
    pdf.set_font("Helvetica", "B", 10)
    pdf.cell(0, 6, "2. Activity Ledger", new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.set_font("Helvetica", "B", 7)
    pdf.set_fill_color(225, 230, 235)
    pdf.cell(15, 6, "Rule", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(15, 6, "Grp", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(75, 6, "Activity Title / Description", 1, align="L", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(20, 6, "Verdict", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(18, 6, "Confirmed", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(18, 6, "Upper", 1, align="C", fill=True, new_x=XPos.RIGHT, new_y=YPos.TOP)
    pdf.cell(29, 6, "Doubt Flags", 1, align="C", fill=True, new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.set_font("Helvetica", "", 7)
    if not engine_res.activities:
        pdf.cell(190, 6, "No activities recorded yet.", 1, align="C", new_x=XPos.LMARGIN, new_y=YPos.NEXT)
    else:
        for act in engine_res.activities:
            flags = ", ".join(act.doubt_codes) if act.doubt_codes else "None"
            pdf.cell(15, 6, str(act.rule_id), 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
            pdf.cell(15, 6, str(act.group), 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
            title = (act.activity_title or "Activity")[:45]
            pdf.cell(75, 6, title, 1, align="L", new_x=XPos.RIGHT, new_y=YPos.TOP)
            pdf.cell(20, 6, str(act.verdict), 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
            pdf.cell(18, 6, f"{act.counted_points_pessimistic}", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
            pdf.cell(18, 6, f"{act.counted_points_optimistic}", 1, align="C", new_x=XPos.RIGHT, new_y=YPos.TOP)
            pdf.cell(29, 6, flags[:18], 1, align="C", new_x=XPos.LMARGIN, new_y=YPos.NEXT)

    pdf.ln(4)

    # Disclaimer Block
    pdf.set_fill_color(255, 248, 220)
    pdf.set_font("Helvetica", "B", 7)
    pdf.cell(0, 4, "MANDATORY STATUTORY DISCLAIMER (agent.md §1.2 & §12.2):", new_x=XPos.LMARGIN, new_y=YPos.NEXT)
    pdf.set_font("Helvetica", "", 6)
    pdf.multi_cell(190, 3, DISCLAIMER_TEXT)
    pdf.ln(5)

    # Signature Block (Rule viii)
    pdf.set_font("Helvetica", "B", 8)
    y = pdf.get_y()
    pdf.line(10, y, 60, y)
    pdf.line(75, y, 125, y)
    pdf.line(140, y, 190, y)
    pdf.text(10, y + 4, "Student Signature")
    pdf.text(75, y + 4, "Staff Advisor (SFA)")
    pdf.text(140, y + 4, "Head of Department (HoD)")

    return bytes(pdf.output())


@router.get("")
def export_activity_points(
    format: str = Query("csv", pattern="^(csv|pdf)$")
) -> Response:
    """Exports the Activity Points File in CSV or PDF format."""
    engine_res = evaluate(store.profile, store.activities, store.ruleset)

    if format == "csv":
        csv_content = generate_csv(engine_res, store.profile)
        return Response(
            content=csv_content,
            media_type="text/csv",
            headers={"Content-Disposition": "attachment; filename=ktu_activity_points.csv"},
        )
    elif format == "pdf":
        pdf_bytes = generate_pdf(engine_res, store.profile)
        return Response(
            content=pdf_bytes,
            media_type="application/pdf",
            headers={"Content-Disposition": "attachment; filename=ktu_activity_points.pdf"},
        )
    raise HTTPException(status_code=400, detail="Invalid format. Supported: 'csv', 'pdf'")
